P = [
 dict(pmid='43050018', doi='10.1007/s10661-026-16162-8', journal='Environ Monit Assess', title='Estimation of spatio-temporal air pollutant emissions from wheat residue burning in the Central Part of India.', tier='C', basis='Satellite-fused', short='NIT Raipur VIIRS FRP-based wheat-residue burning emissions, Madhya Pradesh 2019-2023: 130,766 fires, PM2.5 peak 0.9 Gg (2022)', design='Emission inventory', pm='FRP-based emissions of CO2, CO, PM2.5, OC and EC from VIIRS NOAA-20 active fires masked by SPAM wheat and ESA WorldCover', geo='India (Madhya Pradesh)', endpoint='District-level emissions and hotspots; HYSPLIT transport pathways', affil='National Institute of Technology Raipur, India; National Institute of Technology Raipur, India', n='VIIRS NOAA-20 active fires (130,766 detections after wheat and cropland masking) converted to fire-radiative-power emissions for Madhya Pradesh, 2019-2023. State CO2 ranged 111-161 Gg per year; 2022 peaked with PM2.5 0.9 Gg, OC 0.3 Gg and EC 0.2 Gg; Hoshangabad, Raisen and Vidisha were persistent hotspots; burning concentrated in March-May; HYSPLIT traced transport pathways. Weakness: FRP emission coefficients are not locally validated, small and cloud-obscured fires are missed (the authors call totals lower bounds), and there is no comparison with ground PM. Relevance: indirect - a source inventory for post-harvest burning in central India, where ground monitoring is thin; a distributed sensor network would be the missing check on satellite-derived timing and magnitude.', sub=corpus.EXPO),
 dict(pmid='43048778', doi='10.1080/10934529.2026.2763440', journal='J Environ Sci Health A Tox Hazard Subst Environ Eng', title='Assessment of air quality and heavy metals in residential and commercial areas of Aizawl and Lawngtlai districts, Mizoram.', tier='C', basis='Reference / regulatory monitor', short='Mizoram (Aizawl, Lawngtlai) 2023-2024 fire period: PM10 74 vs 50 ug/m3; breathing difficulty 44% vs 12% between districts', design='Field measurement', pm='Ambient PM10, PM2.5, SPM, gases and heavy metals at residential and commercial sites, site x year x month means', geo='India (Mizoram)', endpoint='Fire vs non-fire concentrations; self-reported respiratory symptoms (n=261)', affil='Mizoram University, India; Pachhunga University College, India', n='Ambient monitoring at residential and commercial sites in Aizawl and Lawngtlai, Mizoram, 2023-2024, aggregated to site-month means, plus a symptom survey of 261 respondents. In the February-March fire period PM10 was 74.20 vs 50.35 ug/m3 (P=0.03) and SPM 131.25 vs 84.70 ug/m3 (P=0.02); PM2.5 31.85 vs 26.69 ug/m3 was method-sensitive (Welch P=0.08, Mann-Whitney P=0.02). Breathing difficulty in the fire period: 43.82% in Aizawl vs 12.00% in Lawngtlai. Weakness: few sites, monthly aggregates and no respondent-level exposure, so the symptom contrast is between districts, not exposures. Relevance: northeast India has almost no continuous monitoring; seasonal fire PM is the signal a low-cost network would resolve daily.', sub=corpus.RESP),
 dict(pmid='43049927', doi='10.1007/s10661-026-16047-w', journal='Environ Monit Assess', title='Environmental footprint of armed conflict in the Gaza Strip: A remote sensing assessment of air, water, and land-use dynamic.', tier='C', basis='Satellite-fused', short='Mansoura/NIOF multi-sensor remote-sensing footprint of the Gaza conflict 2022-2025: aerosol loading up, land-use and water degraded', design='Ecological / spatial', pm='MODIS aerosol loading (AOD) and thermal anomalies alongside Sentinel/Landsat land cover and VIIRS night lights', geo='Middle East', endpoint='Change in aerosol indicators, LULC, vegetation and water quality pre-conflict vs conflict', affil='Mansoura University, Egypt; National Institute of Oceanography and Fisheries, Egypt', n='Multi-sensor satellite time series (Sentinel-1/2, Landsat 8/9, MODIS, VIIRS) for the Gaza Strip, 2022-2025, quantifying land-use change, vegetation loss, surface-water extent and quality proxies, infrastructure disruption, and atmospheric impact via aerosol loading and thermal anomalies. The abstract reports increased atmospheric pollution indicators during the conflict but gives no AOD magnitude, trend or uncertainty. Weakness: column AOD over a strip of about 365 km2 is dominated by regional dust and marine aerosol, so attribution to the conflict without a control region or meteorological adjustment is not established; no surface PM is estimated. Relevance: low-moderate - where in situ monitoring is impossible, this shows the limits of AOD-only inference and the case for rapidly deployable sensors in crises.', sub=corpus.EXPO),
 dict(pmid='', doi='10.1186/s12989-026-00709-1', journal='Particle and Fibre Toxicology', title='In vivo inhalation toxicity of polystyrene nanoplastic particles: PSLT-like responses of apical endpoints and transcriptomic changes', tier='B', basis='Lab / research instrument', short='Nose-only 28-d rat inhalation of respirable polystyrene nanoplastic agglomerates: overload-type lung effects at 50 not 5 mg/m3', design='Animal exposure study', pm='Respirable polystyrene particle agglomerates, nose-only 5 and 50 mg/m3, 6 h/d, 5 d/wk, 28 d; 5 and 13 wk recovery', geo='Not applicable (laboratory)', endpoint='BALF, histopathology, lung and liver transcriptomics', affil='not stated in record; not stated in record', n='Male Wistar rats exposed nose-only to respirable polystyrene agglomerates at 5 and 50 mg/m3 for 28 days, with about 5 and 13 weeks recovery. At 50 mg/m3: neutrophilic infiltration, type II pneumocyte and bronchiolo-alveolar hyperplasia, raised lung weight and persistent particle-associated changes - an overload profile typical of poorly soluble low-toxicity particles. At 5 mg/m3 no adverse apical effects, though lung transcripts in complement, coagulation and lipid pathways shifted; liver changes were minimal. Weakness: one polymer and particle form, male rats only, doses orders of magnitude above ambient airborne microplastic levels. Relevance: indirect - supports treating inhaled low-reactivity plastic particles within the PSLT mass-dose framework rather than as a unique hazard.', sub=corpus.MECH),
]
